<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_admin();require __DIR__.'/../../app/helpers/layout.php';if(is_post()){csrf_check();try{$pdo->prepare('INSERT INTO book_categories(name,description) VALUES(?,?)')->execute([trim($_POST['name']),trim($_POST['description'])]);log_activity($pdo,$u['id'],'admin','Tambah kategori',$_POST['name']);flash('success','Kategori ditambahkan.');}catch(Throwable $e){flash('error','Kategori sudah ada atau tidak valid.');}redirect('/admin/categories/index.php');}render_start('Kategori','Kategori koleksi',$u);dashboard_nav('admin');render_mid('Kategori Buku','Kelola klasifikasi koleksi',$u);$rows=$pdo->query('SELECT c.*,COUNT(b.id) book_count FROM book_categories c LEFT JOIN books b ON b.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();?><div class="grid grid-2"><div class="card"><b>Tambah Kategori</b><form method="post" style="margin-top:14px"><?=csrf_input()?><div class="form-group"><label>Nama</label><input class="input" name="name" required></div><div class="form-group" style="margin-top:12px"><label>Deskripsi</label><textarea name="description" rows="4"></textarea></div><button class="btn btn-primary" style="margin-top:12px">Simpan</button></form></div><div class="card"><b>Daftar Kategori</b><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Nama</th><th>Buku</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['book_count'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php render_end(); ?>
